#ifndef IOS_CHROME_BROWSER_PASSWORDS_INFOBARS_MODEL_IOS_CHROME_PASSWORD_SAVED_INFOBAR_DELEGATE_H_
#define IOS_CHROME_BROWSER_PASSWORDS_INFOBARS_MODEL_IOS_CHROME_PASSWORD_SAVED_INFOBAR_DELEGATE_H_

#import <string>

#import "components/infobars/core/confirm_infobar_delegate.h"

// Delegate for the Infobar displayed after a password is saved. Currently it's
// only displayed after the password was autogenerated or an error preventing
// saving into account was resolved.
class IOSChromePasswordSavedInfoBarDelegate : public ConfirmInfoBarDelegate {
 public:
  explicit IOSChromePasswordSavedInfoBarDelegate(
      std::u16string account_to_store_password);

  IOSChromePasswordSavedInfoBarDelegate(
      const IOSChromePasswordSavedInfoBarDelegate&) = delete;
  IOSChromePasswordSavedInfoBarDelegate& operator=(
      const IOSChromePasswordSavedInfoBarDelegate&) = delete;

  ~IOSChromePasswordSavedInfoBarDelegate() override;

  // ConfirmInfoBarDelegate implementation.
  infobars::InfoBarDelegate::InfoBarIdentifier GetIdentifier() const override;
  std::u16string GetTitleText() const override;
  std::u16string GetMessageText() const override;
  int GetButtons() const override;
  std::u16string GetButtonLabel(InfoBarButton button) const override;
  ui::ImageModel GetIcon() const override;

 private:
  const std::u16string account_to_store_password_;
};

#endif  // IOS_CHROME_BROWSER_PASSWORDS_INFOBARS_MODEL_IOS_CHROME_PASSWORD_SAVED_INFOBAR_DELEGATE_H_
